package unlp.info.bd2.repositories;

import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.repository.CrudRepository;
import unlp.info.bd2.model.Purchase;

import java.util.Date;
import java.util.List;

public interface PurchaseRepository extends JpaRepository<Purchase, Integer> {
    List<Purchase> getPurchasesByRouteId(Long id);
    // Busca las compras por el username del usuario asociado (propiedad nested "user.username")
    Page<Purchase> findByUserUsername(String username, Pageable pageable);
    int countByDateBetween (Date from, Date to);
}
